import {todayISO,localDate,shiftDay,monday,formatDate,formatNumber,clamp,validNum,esc,weeklyTotals,sessionVolume,exerciseHistory,paceFrom,formatPace,initialLog,sortSessions,uniqueId,chartPolyline} from './utils.mjs';
import {loadState,saveState} from './store.mjs';
const $=s=>document.querySelector(s);
const app=$('#app');
const glyphs={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/><path d="M9 21v-8h6v8"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',activity:'<path d="M22 12h-4l-3 8-6-16-3 8H2"/>',stats:'<path d="M4 20V10m6 10V4m6 16v-7m5 7H2"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',play:'<path d="m8 5 11 7-11 7z"/>',pause:'<rect x="6" y="5" width="4" height="14" rx="1"/><rect x="14" y="5" width="4" height="14" rx="1"/>',check:'<path d="m4 12 5 5L20 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="M5 5 19 19M19 5 5 19"/>',back:'<path d="m15 18-6-6 6-6"/>',next:'<path d="m9 18 6-6-6-6"/>',edit:'<path d="M12 20h9M4 16l-.5 4.5L8 20 19 9l-5-5L4 16Z"/><path d="m12 6 5 5"/>',trash:'<path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6m5 4v7m4-7v7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',mountain:'<path d="m2 20 8-15 4 7 3-4 5 12z"/>',run:'<circle cx="14" cy="4" r="2"/><path d="m5 19 4-4 3 2 5 4M10 10l4 2 2 5M10 10l-4 4M10 10l3-3 5 2"/>',weight:'<path d="M5 12h14M3 9v6m18-6v6M7 7v10m10-10v10"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 18v3h16v-3"/>',upload:'<path d="M12 21V8m-5 5 5-5 5 5M4 6V3h16v3"/>',refresh:'<path d="M20 7A8 8 0 0 0 6 5L4 7m0-5v5h5M4 17a8 8 0 0 0 14 2l2-2m0 5v-5h-5"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10v.01"/>',bar:'<path d="M3 3v18h18M6 17l5-6 4 3 5-8"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',spark:'<path d="m12 3 1.8 6.2L20 11l-6.2 1.8L12 19l-1.8-6.2L4 11l6.2-1.8L12 3Z"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',shoe:'<path d="M2 17v3h20v-6l-6-2-5-5-3 2 2 5-8 1v2Z"/>',ruler:'<path d="M4 3h16v18H4zM4 8h5M4 12h3M4 16h5"/>'};
function icon(name,sz=20){return `<svg aria-hidden="true" viewBox="0 0 24 24" width="${sz}" height="${sz}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${glyphs[name]||glyphs.activity}</svg>`;}
const category=(type)=>type==='force'?'Musculation':type==='cardio'?'Course / cardio':'Mixte';
const weekStart='2026-11-09';
let state, page='home', selectedDate=todayISO(), sessionId=null, draft=null, modal=null, chartType='kilometres', calendarView='week', intervalConfig={warmup:10,rounds:6,work:1,rest:2,cooldown:6,workIncline:'',workSpeed:''}, interval=null, restTimer=null, toastTimeout, saveTimeout, saveChain=Promise.resolve(), storageMode='IndexedDB';
function toast(msg){$('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=msg;document.body.appendChild(el);clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.remove(),2900);}
function persist(){clearTimeout(saveTimeout);saveTimeout=setTimeout(()=>{const snapshot=structuredClone(state);saveChain=saveChain.catch(()=>{}).then(()=>saveState(snapshot)).catch(err=>{try{localStorage.setItem('hybridtrack-fallback',JSON.stringify(snapshot));storageMode='Stockage de secours';}catch(e){storageMode='ERREUR : export conseillé';toast('Sauvegarde impossible : exporte tes données !');} console.warn('Sauvegarde IndexedDB indisponible',err);});},130);}
const sget=(id)=>state.sessions.find(s=>s.id===id)||state.archivedSessions?.find(s=>s.id===id);
const logsOf=(id)=>state.logs.filter(l=>l.sessionId===id);
const latestLog=(id)=>logsOf(id).sort((a,b)=>b.startedAt.localeCompare(a.startedAt))[0];
const done=(s)=>logsOf(s.id).some(l=>l.finishedAt);
function inProgress(id){return logsOf(id).find(l=>!l.finishedAt);}
const badge=(s)=>`<span class="pill ${esc(s.type)}">${icon(s.type==='force'?'weight':s.type==='cardio'?'run':'activity',13)} ${category(s.type)}</span>`;
function relativeWeek(){const diff=(localDate(todayISO())-localDate(weekStart))/86400000;return Math.floor(diff/7)+1;}
function sectionHead(title,action=''){return `<div class="section-title"><h2>${title}</h2>${action}</div>`;}
function sessionCard(s,compact=false){const completed=done(s),ongoing=!!inProgress(s.id);return `<div class="activity"><div class="row spread start"><div>${badge(s)}</div>${completed?'<span class="pill done">✓ Terminée</span>':ongoing?'<span class="pill">En cours</span>':`<span class="pill">${icon('clock',12)} ${esc(s.durationLabel||s.durationMin+' min')}</span>`}</div><h3>${esc(s.title)}</h3><p class="desc">${esc(s.description||'Séance personnalisée')}</p><div class="meta"><span>${icon('calendar',14)} ${formatDate(s.date,{weekday:'short',day:'numeric',month:'short'})}</span><span>${s.exercises.length} exercices</span>${s.week?`<span>Semaine ${s.week}</span>`:''}</div><div class="btnrow"><button class="btn ${compact?'':'accent'}" data-action="view-session" data-id="${esc(s.id)}">${ongoing?'Reprendre':completed?'Voir le bilan':'Voir la séance'} ${icon('next',16)}</button>${compact?`<button class="btn outline icon-only" title="Dupliquer" data-action="duplicate" data-id="${esc(s.id)}">${icon('copy')}</button>`:''}</div></div>`;}
function nextSession(){const cur=todayISO();return sortSessions(state.sessions).find(s=>s.date>=cur&&!done(s))||sortSessions(state.sessions).find(s=>!done(s))||null;}
function home(){const now=todayISO(),wk=monday(now),t=weeklyTotals(state.logs,wk),weekSessions=state.sessions.filter(s=>s.date>=wk&&s.date<shiftDay(wk,7)),active=state.sessions.filter(s=>s.date===now&&!done(s))[0]||nextSession(),totalDone=state.sessions.filter(done).length,weekNumber=relativeWeek(),days=Math.ceil((localDate('2027-08-07')-localDate(now))/86400000);return `<div class="section-intro"><div><div class="eyebrow">Ton espace d'entraînement</div><h1>La régularité, d'abord.</h1><p class="lede">Chaque séance compte. Un pas après l'autre.</p></div></div><div class="desktop-cols"><div class="grid"><section class="panel hero"><div class="eyebrow">${active&&active.date===now?'AUJOURD’HUI':'PROCHAINE SÉANCE'}</div><h1>${active?esc(active.title):'Programme terminé !'}</h1><p class="lede">${active?esc(active.description||'Construis ta progression, à ton rythme.'):'Bravo pour ton engagement. Tu peux créer un nouveau bloc.'}</p><div style="height:20px"></div><button class="btn accent" data-action="${active?'view-session':'new-session'}" ${active?`data-id="${esc(active.id)}"`:''}>${icon('play',17)} ${active?'Ouvrir la séance':'Créer une séance'}</button></section><div class="kpis"><div class="kpi"><div class="n">${t.count}<span class="muted" style="font-size:15px">/${weekSessions.length}</span></div><div class="label">Séances / semaine</div></div><div class="kpi"><div class="n">${formatNumber(t.km)}</div><div class="label">Kilomètres courus</div></div><div class="kpi"><div class="n">${formatNumber(t.elevation,0)}</div><div class="label">Dénivelé + (m)</div></div></div><section class="panel"><div class="row spread"><h3>Programme initial</h3><span class="pill">${totalDone} / ${state.sessions.filter(s=>!!s.week).length}</span></div><div class="progress"><span style="width:${clamp(100*totalDone/Math.max(state.sessions.filter(s=>!!s.week).length,1),0,100)}%"></span></div><div class="row spread" style="margin:12px 0 0"><small>${weekNumber>=1&&weekNumber<=8?`Semaine ${weekNumber} sur 8`:weekNumber<1?'Début le 9 novembre':'Bloc de reprise achevé'}</small><small>${Math.round(100*totalDone/Math.max(state.sessions.filter(s=>!!s.week).length,1))}% complété</small></div><div class="weekbar" style="margin-top:16px">${Array.from({length:8},(_,i)=>{const ls=state.sessions.filter(s=>s.week===i+1),dn=ls.filter(done).length;return `<button class="weekitem ${weekNumber===i+1?'active':''}" data-action="go-week" data-week="${i+1}"><strong>S${i+1}</strong><small>${dn}/${ls.length}</small></button>`;}).join('')}</div></section></div><div class="grid"><section class="panel"><div class="row spread"><div><div class="eyebrow">LE GRAND OBJECTIF</div><h2 style="margin-top:8px">${esc(state.profile.raceName||'Sierre–Zinal 2027')}</h2></div><div class="miniicon">${icon('mountain',23)}</div></div><div class="kpis" style="margin-top:18px"><div class="kpi"><div class="n" style="font-size:23px">${formatNumber(state.profile.raceDistance||31,0)}</div><div class="label">km</div></div><div class="kpi"><div class="n" style="font-size:23px">${formatNumber(state.profile.raceElevation||2200,0)}</div><div class="label">m D+</div></div><div class="kpi"><div class="n" style="font-size:23px">${Math.max(0,days)}</div><div class="label">jours restants</div></div></div><p class="lede tiny" style="margin-top:15px">Objectif : construire une base solide avant une préparation trail spécifique.</p></section><section class="panel"><div class="row spread"><h3>Cette semaine</h3><button class="btn ghost small" data-action="nav" data-page="calendar">Voir le planning ${icon('next',14)}</button></div><div class="list">${weekSessions.length?sortSessions(weekSessions).map(s=>`<div class="listitem clickable" data-action="view-session" data-id="${esc(s.id)}"><span class="categorydot ${s.type}"></span><div class="grow"><div class="name">${esc(s.title)}</div><div class="sub">${formatDate(s.date,{weekday:'short',day:'numeric'})}</div></div>${done(s)?icon('check'):icon('next')}</div>`).join(''):'<div class="empty">Aucune séance cette semaine.</div>'}</div></section><section class="panel soft"><div class="row start"><div class="miniicon">${icon('spark')}</div><div><strong>Le suivi, sans pression</strong><p class="muted tiny" style="margin-top:5px">Tu peux déplacer une séance ou noter une sortie de ski. Le programme reste flexible.</p></div></div></section></div></div>`;}
function calendar(){const wk=monday(selectedDate),days=Array.from({length:7},(_,i)=>shiftDay(wk,i));const selected=sortSessions(state.sessions.filter(s=>s.date===selectedDate));const wkDates=wk>=weekStart?Math.floor((localDate(wk)-localDate(weekStart))/604800000)+1:null;return `<div class="section-intro"><div><div class="eyebrow">PLANNING</div><h1>Ton calendrier</h1><p class="lede">Planifie, déplace et personnalise chaque séance.</p></div><button class="btn accent" data-action="new-session">${icon('plus')} <span>Créer</span></button></div><section class="panel"><div class="calendar-head"><div class="row"><button class="btn icon-only outline" data-action="change-week" data-direction="-1" aria-label="Semaine précédente">${icon('back')}</button><div><strong>${formatDate(wk,{day:'numeric',month:'short'})} – ${formatDate(shiftDay(wk,6),{day:'numeric',month:'short',year:'numeric'})}</strong><div class="muted tiny">${wkDates&&wkDates>0&&wkDates<=8?`Semaine ${wkDates} du programme`:'Planning personnalisé'}</div></div><button class="btn icon-only outline" data-action="change-week" data-direction="1" aria-label="Semaine suivante">${icon('next')}</button></div><div class="seg"><button class="${calendarView==='week'?'sel':''}" data-action="calendar-mode" data-mode="week">7 j</button><button class="${calendarView==='month'?'sel':''}" data-action="calendar-mode" data-mode="month">Mois</button></div></div>${calendarView==='week'?`<div class="days">${days.map(d=>{const sessions=state.sessions.filter(s=>s.date===d);return `<button class="day ${selectedDate===d?'selected':''} ${todayISO()===d?'today':''}" data-action="select-day" data-date="${d}"><span class="dow">${formatDate(d,{weekday:'short'})}</span><strong>${localDate(d).getDate()}</strong><span class="dots">${sessions.slice(0,3).map(s=>`<i class="${s.type}"></i>`).join('')}</span></button>`;}).join('')}</div>`:monthGrid()}<div class="row spread"><div><h3>${formatDate(selectedDate,{weekday:'long',day:'numeric',month:'long'})}</h3><small>${selected.length} séance${selected.length>1?'s':''} prévue${selected.length>1?'s':''}</small></div><button class="btn small outline" data-action="today">Aujourd'hui</button></div></section>${selected.length?`<div class="grid grid2" style="margin-top:14px">${selected.map(s=>sessionCard(s,true)).join('')}</div>`:`<div class="empty" style="margin-top:15px"><p>Pas de séance prévue ce jour.</p><button class="btn outline" style="margin-top:12px" data-action="new-session">${icon('plus')} Ajouter une séance</button></div>`}<div class="row spread" style="margin-top:24px"><h2>Tout le programme</h2><span class="pill">${state.sessions.length} séances</span></div><div class="list">${sortSessions(state.sessions).filter(s=>s.date>=shiftDay(selectedDate,-4)&&s.date<=shiftDay(selectedDate,21)).map(s=>`<div class="listitem clickable" data-action="view-session" data-id="${esc(s.id)}"><div class="miniicon">${icon(s.type==='force'?'weight':s.type==='cardio'?'run':'activity')}</div><div class="grow"><div class="name">${esc(s.title)}</div><div class="sub">${formatDate(s.date,{weekday:'short',day:'numeric',month:'short'})} · ${esc(s.durationLabel||'Libre')}</div></div>${done(s)?'<span class="pill done">✓</span>':icon('next')}</div>`).join('')||'<div class="empty">Aucune séance à proximité de la date choisie.</div>'}</div>`;}
function monthGrid(){const d=localDate(selectedDate),yr=d.getFullYear(),mo=d.getMonth();const first=new Date(yr,mo,1,12),firstOffset=(first.getDay()+6)%7,start=new Date(yr,mo,1-firstOffset,12);return `<div class="monthlabel-row" style="margin-top:15px">${['L','M','M','J','V','S','D'].map(x=>`<div class="monthlabel">${x}</div>`).join('')}</div><div class="monthgrid">${Array.from({length:42},(_,i)=>{const cur=new Date(start.getFullYear(),start.getMonth(),start.getDate()+i,12),iso=todayISO(cur),ss=state.sessions.filter(s=>s.date===iso);return `<button class="monthcell ${cur.getMonth()!==mo?'dim':''} ${selectedDate===iso?'selected':''} ${todayISO()===iso?'today':''}" data-action="select-day" data-date="${iso}"><span>${cur.getDate()}</span><span class="countdot">${ss.slice(0,3).map(()=>'<span></span>').join('')}</span></button>`;}).join('')}</div>`;}
function sessionDetails(){const s=sget(sessionId);if(!s){page='calendar';return calendar();}const l=inProgress(s.id)||latestLog(s.id),complete=l?.finishedAt;const plannedOnly=!l;return `<div class="section-intro"><div><button class="btn ghost small" data-action="nav" data-page="calendar">${icon('back')} Planning</button><div style="height:12px"></div><div class="eyebrow">${formatDate(s.date,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div><h1>${esc(s.title)}</h1><p class="lede">${esc(s.description||'Séance personnalisée')} · ${esc(s.durationLabel||s.durationMin+' min')}</p></div><div class="btnrow"><button class="btn outline icon-only" title="Modifier" data-action="edit-session" data-id="${esc(s.id)}">${icon('edit')}</button><button class="btn outline icon-only" title="Dupliquer" data-action="duplicate" data-id="${esc(s.id)}">${icon('copy')}</button></div></div><div class="desktop-cols"><div><section class="panel"><div class="row spread start"><div>${badge(s)} ${s.week?`<span class="pill">Semaine ${s.week}</span>`:''}</div>${complete?'<span class="pill done">✓ Terminée</span>':l?'<span class="pill">● En cours</span>':'<span class="pill">À faire</span>'}</div>${s.advice?`<div class="softcall" style="margin-top:15px"><strong>Conseil du programme</strong><p style="margin-top:5px">${esc(s.advice)}</p></div>`:''}${plannedOnly?`<div class="list" style="margin-top:15px">${s.exercises.map((e,i)=>`<div class="listitem"><span style="color:var(--accent);font-weight:750">${i+1}.</span><div class="grow"><div class="name">${esc(e.name)}</div><div class="sub">${esc(e.volume)} · ${esc(e.load)}</div>${e.description?`<div class="sub" style="margin-top:4px">${esc(e.description)}</div>`:''}</div></div>`).join('')}</div><div style="height:15px"></div><button class="btn accent block" data-action="start-session" data-id="${esc(s.id)}">${icon('play')} Commencer cette séance</button>`:workoutLogger(s,l)}</section></div><div class="grid">${s.type!=='force'?`<section class="panel">${sectionHead('Intervalles guidés','')}<p class="muted tiny">Configure un entraînement fractionné et suis les phases directement sur l'écran.</p><button class="btn outline block" style="margin-top:15px" data-action="open-timer" data-id="${esc(s.id)}">${icon('clock')} Ouvrir le chronomètre</button></section>`:''}<section class="panel"><h3>Informations</h3><div class="mini-stats"><span>${icon('clock',15)} ${esc(s.durationLabel||s.durationMin+' min')}</span><span>${icon('activity',15)} ${s.exercises.length} exercices</span></div><div class="divider"></div><p class="muted tiny">Les charges indiquées proviennent de ton programme et sont des repères de départ, pas des obligations.</p>${complete?`<div class="divider"></div><div class="row spread"><span class="muted">Volume effectué</span><strong>${formatNumber(sessionVolume(l),0)} kg</strong></div><div style="height:10px"></div><button class="btn outline block" data-action="restart-session" data-id="${esc(s.id)}">${icon('refresh')} Refaire la séance</button>`:''}</section><section class="panel soft"><div class="row start"><div class="miniicon">${icon('info')}</div><p class="tiny muted">Pendant une séance, chaque série validée est sauvegardée localement. Termine la séance pour l'inclure dans tes statistiques.</p></div></section></div></div>`;}
function lastExerciseText(name,exceptLog){let histories=exerciseHistory(state.logs.filter(l=>l.id!==exceptLog),name);let h=histories.find(a=>a.sets.some(t=>t.done));if(!h)return 'Aucun historique';const sets=h.sets.filter(x=>x.done);return `${formatDate(h.date)} · ${sets.length} séries · ${sets.map(x=>`${x.kg||'—'} kg × ${x.reps||'—'}`).join(' / ')}`;}
function workoutLogger(s,l){const disabled=!!l.finishedAt;return `<div class="divider"></div>${disabled?`<div class="alert success">Séance terminée le ${new Date(l.finishedAt).toLocaleDateString('fr-CH')}. Les données sont enregistrées.</div>`:`<div class="row spread"><strong class="tiny">Séance en cours</strong><button class="btn small outline" data-action="rest-start" data-seconds="90">${icon('clock',14)} Repos 90 s</button></div><div id="rest-strip" class="softcall hide" style="margin-top:10px"></div>`}<div style="margin-top:11px">${l.exercises.map((e,i)=>`<div class="ex-card"><div class="row spread start"><div class="grow"><div class="eyebrow" style="font-size:10px">EXERCICE ${i+1}/${l.exercises.length}</div><h4>${esc(e.name)}</h4><p class="hint">${esc(e.volume||'À définir')} · ${esc(e.load||'Charge libre')}</p></div>${e.sets.every(a=>a.done)?`<span class="pill done">${icon('check',12)} Fait</span>`:''}</div>${e.description?`<details><summary class="muted tiny">${icon('info',12)} Voir la technique</summary><div class="explain">${esc(e.description)}</div></details>`:''}<div class="history">${icon('refresh',12)} ${esc(lastExerciseText(e.name,l.id))}</div><div class="sethead"><span>Série</span><span>kg</span><span>Rép.</span><span>OK</span></div><div class="sets">${e.sets.map((a,j)=>`<div class="set-row"><span class="num">${j+1}</span><input type="number" inputmode="decimal" min="0" step="0.5" aria-label="Charge de la série ${j+1}" placeholder="kg" value="${esc(a.kg)}" data-logid="${l.id}" data-eidx="${i}" data-sidx="${j}" data-setfield="kg" ${disabled?'disabled':''}><input type="number" inputmode="numeric" min="0" step="1" aria-label="Répétitions série ${j+1}" placeholder="${e.isTimed?'—':'rép.'}" value="${esc(a.reps)}" data-logid="${l.id}" data-eidx="${i}" data-sidx="${j}" data-setfield="reps" ${disabled?'disabled':''}><button class="checkset ${a.done?'done':''}" aria-label="Valider la série ${j+1}" data-action="toggle-set" data-eidx="${i}" data-sidx="${j}" ${disabled?'disabled':''}>${icon('check',18)}</button></div>`).join('')}</div>${!disabled?`<button class="btn ghost small" style="margin-top:9px" data-action="add-set" data-eidx="${i}">${icon('plus',14)} Ajouter une série</button>`:''}</div>`).join('')}</div><div class="divider"></div><h3>Données de la séance</h3><div class="formgrid" style="margin-top:12px">${[['durationMin','Durée (min)'],['distance','Distance (km)'],['elevation','Dénivelé + (m)'],['descent','Dénivelé − (m)'],['hrAvg','FC moyenne (bpm)'],['hrMax','FC max (bpm)'],['speed','Vitesse tapis (km/h)'],['incline','Pente tapis (%)']].map(([k,label])=>`<div class="field"><label>${label}</label><input type="number" inputmode="decimal" min="0" step="any" data-cardiofield="${k}" value="${esc(l.cardio?.[k]??'')}" ${disabled?'disabled':''}></div>`).join('')}<div class="field"><label>Effort ressenti (RPE /10)</label><input type="number" min="0" max="10" step="0.5" data-logfield="rpe" value="${esc(l.rpe||'')}" ${disabled?'disabled':''}></div><div class="field full"><label>Notes et sensations</label><textarea rows="3" data-logfield="notes" ${disabled?'disabled':''} placeholder="Énergie, difficultés, sensations…">${esc(l.notes)}</textarea></div></div><div id="cardio-preview" class="softcall" style="margin-top:12px">${cardioPreview(l)}</div><div class="row spread" style="margin:13px 0"><small>Volume validé</small><strong>${formatNumber(sessionVolume(l),0)} kg</strong></div>${!disabled?`<div class="logactions"><button class="btn accent block" data-action="finish-session">${icon('check')} Terminer et enregistrer la séance</button></div>`:`<div style="height:12px"></div><button class="btn outline block" data-action="nav" data-page="stats">${icon('stats')} Voir ma progression</button>`}`;}
function cardioPreview(l){const d=Number(l.cardio?.distance),minutes=Number(l.cardio?.durationMin);const pace=paceFrom(d,minutes);const speed=minutes>0&&d>0?60*d/minutes:0;return d>0&&minutes>0?`<strong>Allure moyenne : ${formatPace(pace)} · ${formatNumber(speed,1)} km/h</strong>`:'<span class="muted">Saisis la durée et la distance pour calculer ton allure moyenne.</span>';}
function sessionSummaryLine(l){const km=Number(l.cardio?.distance)||0;return `${l.type==='cardio'?'Course / cardio':category(l.type)} · ${km?`${formatNumber(km)} km · `:''}${formatNumber(sessionVolume(l),0)} kg volume`}
function trainings(){const scheduled=sortSessions(state.sessions).filter(s=>!done(s));const completed=[...state.logs].filter(l=>l.finishedAt).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="section-intro"><div><div class="eyebrow">MON CARNET</div><h1>Mes entraînements</h1><p class="lede">Ton historique, tes séances et tes exercices.</p></div><button class="btn accent" data-action="new-session">${icon('plus')} Séance</button></div><div class="grid grid2"><section class="panel"><div class="row spread"><h3>À venir</h3><span class="pill">${scheduled.length}</span></div><div class="list">${scheduled.slice(0,7).map(s=>`<div class="listitem clickable" data-action="view-session" data-id="${esc(s.id)}"><span class="categorydot ${s.type}"></span><div class="grow"><div class="name">${esc(s.title)}</div><div class="sub">${formatDate(s.date,{weekday:'short',day:'numeric',month:'short'})}</div></div>${icon('next')}</div>`).join('')||'<div class="empty">Aucune séance en attente.</div>'}</div></section><section class="panel"><div class="row spread"><h3>Séances réalisées</h3><span class="pill done">${completed.length}</span></div><div class="list">${completed.slice(0,10).map(l=>`<div class="listitem clickable" data-action="view-session" data-id="${esc(l.sessionId)}"><div class="miniicon">${icon('check')}</div><div class="grow"><div class="name">${esc(l.title)}</div><div class="sub">${formatDate(l.date)} · ${esc(sessionSummaryLine(l))}</div></div>${icon('next')}</div>`).join('')||'<div class="empty">Tes séances terminées apparaîtront ici.</div>'}</div></section></div>${sectionHead('Bibliothèque d’exercices',`<button class="btn outline small" data-action="new-exercise">${icon('plus',14)} Ajouter</button>`)}<section class="panel"><p class="muted tiny" style="margin-bottom:11px">Exercices du programme et exercices personnalisés. Tu peux les ajouter dans tes séances.</p><div class="list" style="max-height:310px;overflow:auto">${allExerciseNames().map(e=>`<div class="listitem"><div class="grow"><div class="name">${esc(e.name)}</div><div class="sub">${esc(e.description||'Exercice personnalisable')}</div></div>${state.customExercises.some(x=>x.id===e.id)?`<button class="btn ghost icon-only" data-action="delete-exercise" data-id="${esc(e.id)}" title="Supprimer">${icon('trash',15)}</button>`:''}</div>`).join('')}</div></section>`;}
function allExerciseNames(){const map=new Map();for(const s of state.sessions)for(const e of s.exercises){const key=e.name.trim().toLocaleLowerCase('fr');if(!map.has(key))map.set(key,{name:e.name,description:e.description,load:e.load,volume:e.volume,id:e.id});}for(const e of state.customExercises)map.set(e.name.trim().toLocaleLowerCase('fr'),e);return [...map.values()].sort((a,b)=>a.name.localeCompare(b.name,'fr'));}
function graph(series,type='line'){if(!series?.length||series.every(a=>a.value===0))return `<div class="empty">Pas encore de données à afficher.</div>`;if(type==='bar'){const max=Math.max(...series.map(x=>x.value),1);return `<div class="barrow">${series.map(x=>`<div class="barcol"><div title="${esc(x.label)} : ${formatNumber(x.value)}" style="height:${Math.max(2,(x.value/max)*110)}px"></div><small>${esc(x.label)}</small></div>`).join('')}</div>`;}const w=330,h=140,pts=chartPolyline(series,w,h,15);return `<svg class="chart plot" viewBox="0 0 ${w} ${h}" aria-label="Courbe d'évolution" role="img"><path d="M15 ${h-15}H${w-15}" stroke="#45596b" fill="none"/><polyline points="${pts}" stroke="#c8f66d" stroke-width="3" stroke-linejoin="round" stroke-linecap="round" fill="none"/>${pts.split(' ').map(t=>{const [x,y]=t.split(',');return `<circle cx="${x}" cy="${y}" r="4.5" fill="#c8f66d" stroke="#183327" stroke-width="2"><title>${formatNumber(series[pts.split(' ').indexOf(t)]?.value)}</title></circle>`;}).join('')}</svg><div class="axislabels"><span>${esc(series[0].label)}</span><span>${esc(series.at(-1).label)}</span></div>`;}
function statSeries(metric){const wk=monday(todayISO());return Array.from({length:8},(_,i)=>{const date=shiftDay(wk,(i-7)*7),x=weeklyTotals(state.logs,date);return {label:`S${i+1}`,date,value:metric==='kilometres'?x.km:metric==='denivele'?x.elevation:metric==='volume'?Math.round(x.volume):metric==='duree'?x.mins:x.count};});}
function personalRecords(){const map=new Map();for(const l of state.logs.filter(l=>l.finishedAt))for(const e of l.exercises)for(const a of e.sets||[]){const kg=Number(a.kg),reps=Number(a.reps);if(!a.done||!kg||!reps)continue;const key=e.name.toLowerCase().trim();let old=map.get(key);if(!old||kg>old.kg||(kg===old.kg&&reps>old.reps))map.set(key,{name:e.name,kg,reps,date:l.date});}return [...map.values()].sort((a,b)=>b.kg-a.kg);}
function stats(){const t=weeklyTotals(state.logs,monday(todayISO())),completed=state.logs.filter(l=>l.finishedAt),km=completed.reduce((s,l)=>s+validNum(l.cardio?.distance),0),elev=completed.reduce((s,l)=>s+validNum(l.cardio?.elevation),0),pr=personalRecords(),fields=[['kilometres','Kilomètres'],['denivele','Dénivelé'],['volume','Musculation'],['duree','Minutes'],['seances','Séances']];const series=statSeries(chartType),measures=[...state.measures].sort((a,b)=>a.date.localeCompare(b.date)),lastMeasure=measures.at(-1)||{};return `<div class="section-intro"><div><div class="eyebrow">STATISTIQUES</div><h1>Ta progression</h1><p class="lede">Des faits concrets, semaine après semaine.</p></div><button class="btn accent" data-action="new-measure">${icon('plus')} Mesures</button></div><div class="grid"><div class="kpis"><div class="kpi"><div class="n">${completed.length}</div><div class="label">Séances terminées</div></div><div class="kpi"><div class="n">${formatNumber(km)}</div><div class="label">km cumulés</div></div><div class="kpi"><div class="n">${formatNumber(elev,0)}</div><div class="label">m D+ cumulés</div></div></div><div class="desktop-cols"><section class="panel"><h3>Évolution hebdomadaire</h3><div class="metric-list">${fields.map(([key,label])=>`<button class="btn small ${chartType===key?'accent':'outline'}" data-action="metric" data-metric="${key}">${label}</button>`).join('')}</div>${graph(series,'bar')}<div class="row spread" style="margin-top:14px"><span class="muted tiny">Cette semaine</span><strong>${formatNumber(series.at(-1)?.value||0,chartType==='kilometres'?1:0)} ${chartType==='kilometres'?'km':chartType==='denivele'?'m':chartType==='volume'?'kg':chartType==='duree'?'min':'séance(s)'}</strong></div></section><section class="panel"><div class="row spread"><h3>Composition corporelle</h3><button class="btn outline small" data-action="new-measure">${icon('plus',14)} Saisir</button></div><div class="grid grid2"><div class="measure"><small>Dernier poids</small><strong>${lastMeasure.weight?`${formatNumber(lastMeasure.weight)} kg`:'—'}</strong></div><div class="measure"><small>Tour de taille</small><strong>${lastMeasure.waist?`${formatNumber(lastMeasure.waist)} cm`:'—'}</strong></div></div><div style="height:12px"></div><small>Évolution du poids (kg)</small>${graph(measures.filter(m=>m.weight).map(m=>({label:formatDate(m.date),value:Number(m.weight)})).slice(-12))}<p class="muted tiny" style="margin-top:12px">Le poids ne résume pas ta progression : les performances et les sensations comptent aussi.</p></section></div><div class="desktop-cols"><section class="panel"><div class="row spread"><h3>Records enregistrés</h3><span class="pill">${pr.length}</span></div><div class="list">${pr.slice(0,10).map(x=>`<div class="listitem"><div class="grow"><div class="name">${esc(x.name)}</div><div class="sub">${formatDate(x.date)}</div></div><strong>${formatNumber(x.kg)} kg × ${x.reps}</strong></div>`).join('')||'<div class="empty">Valide tes séries avec une charge pour voir apparaître tes records.</div>'}</div></section><section class="panel"><h3>Historique des mesures</h3><div class="list">${[...measures].reverse().slice(0,12).map(m=>`<div class="listitem"><div class="grow"><div class="name">${formatDate(m.date,{day:'numeric',month:'long',year:'numeric'})}</div><div class="sub">${m.weight?formatNumber(m.weight)+' kg':''}${m.waist?' · taille '+formatNumber(m.waist)+' cm':''}</div></div><button class="btn ghost icon-only" data-action="delete-measure" data-id="${esc(m.id)}" title="Supprimer une mesure">${icon('trash',15)}</button></div>`).join('')||'<div class="empty">Ajoute une mesure pour suivre son évolution.</div>'}</div></section></div></div>`;}
function profile(){return `<div class="section-intro"><div><div class="eyebrow">PERSONNALISATION</div><h1>Ton espace</h1><p class="lede">Réglages, objectifs et sauvegardes.</p></div></div><div class="desktop-cols"><div class="grid"><section class="panel"><h3>Profil sportif</h3><div class="formgrid"><div class="field"><label>Taille (cm)</label><input type="number" inputmode="decimal" min="0" max="260" data-profile="height" value="${esc(state.profile.height||'')}"></div><div class="field"><label>Objectif principal</label><select data-profile="goal"><option value="hybrid" ${state.profile.goal==='hybrid'?'selected':''}>Hybride : force + course</option><option value="strength" ${state.profile.goal==='strength'?'selected':''}>Musculation</option><option value="running" ${state.profile.goal==='running'?'selected':''}>Course / trail</option></select></div><div class="field full"><label>Nom de ton objectif</label><input data-profile="raceName" value="${esc(state.profile.raceName||'')}"></div><div class="field"><label>Date objectif</label><input type="date" data-profile="raceDate" value="${esc(state.profile.raceDate||'2027-08-07')}"></div><div class="field"><label>Repos par défaut (s)</label><input type="number" inputmode="numeric" min="10" max="600" data-profile="restSeconds" value="${esc(state.profile.restSeconds||90)}"></div><div class="field"><label>Distance objectif (km)</label><input type="number" min="1" step="any" data-profile="raceDistance" value="${esc(state.profile.raceDistance||31)}"></div><div class="field"><label>Dénivelé objectif (m D+)</label><input type="number" min="0" step="1" data-profile="raceElevation" value="${esc(state.profile.raceElevation||2200)}"></div></div><p class="muted tiny" style="margin-top:12px">Les modifications sont enregistrées automatiquement.</p></section><section class="panel"><h3>Ton programme</h3><div class="mini-stats"><span>${state.sessions.length} séances planifiées</span><span>${state.sessions.filter(s=>s.week).length} séances du PDF</span></div><div class="divider"></div><button class="btn outline block" data-action="nav" data-page="calendar">${icon('calendar')} Ouvrir le calendrier</button></section></div><div class="grid"><section class="panel"><h3>Sauvegarder tes données</h3><p class="muted tiny">Les données restent sur cet appareil et dans ce navigateur. Elles ne sont pas synchronisées entre appareils. Fais régulièrement une sauvegarde externe.</p><div class="grid" style="margin-top:16px"><button class="btn accent block" data-action="export-json">${icon('download')} Exporter une sauvegarde complète (JSON)</button><button class="btn outline block" data-action="export-csv">${icon('download')} Exporter les séances (CSV)</button><button class="btn outline block" data-action="trigger-import">${icon('upload')} Restaurer une sauvegarde JSON</button><input id="import-file" type="file" accept="application/json,.json"></div><div class="divider"></div><div class="status">${icon('check',14)} Mode de stockage : <strong>${esc(storageMode)}</strong></div></section><section class="panel soft"><h3>Installation sur iPhone</h3><p class="muted tiny">Une fois l'application publiée en HTTPS : ouvre-la dans Safari, touche Partager, puis « Sur l'écran d'accueil ».</p><p class="muted tiny" style="margin-top:12px">Le mode hors connexion fonctionne après le premier chargement complet. Pour les chronomètres, laisse l'application au premier plan.</p></section></div></div>`;}
function presetFor(s){if(!s||!s.week)return {warmup:8,rounds:6,work:1,rest:2,cooldown:5,workIncline:'',workSpeed:''};const map={1:[6,3,5,2,4,'5-8',''],2:[6,3,4,3,5,'5-7',''],3:[10,6,1,2,6,'1','9-12'],4:[7,4,4,2,5,'7-11',''],5:[8,5,2,2,7,'1',''],6:[7,1,15,15,5,'6-9',''],7:[10,6,1.5,2,7,'3-5',''],8:[6,1,25,0,4,'1','']};const v=map[s.week];return {warmup:v[0],rounds:v[1],work:v[2],rest:v[3],cooldown:v[4],workIncline:v[5],workSpeed:v[6]};}
function buildPhases(cfg){const p=[];if(validNum(cfg.warmup)>0)p.push({label:'Échauffement',minutes:validNum(cfg.warmup),phase:'warmup'});for(let n=1;n<=Math.floor(validNum(cfg.rounds));n++){if(validNum(cfg.work)>0)p.push({label:`Effort ${n}/${cfg.rounds}`,minutes:validNum(cfg.work),phase:'work'});if(validNum(cfg.rest)>0)p.push({label:`Récupération ${n}/${cfg.rounds}`,minutes:validNum(cfg.rest),phase:'rest'});}if(validNum(cfg.cooldown)>0)p.push({label:'Retour au calme',minutes:validNum(cfg.cooldown),phase:'cool'});return p;}
function countdown(ms){ms=Math.max(0,Math.ceil(ms/1000));return `${String(Math.floor(ms/60)).padStart(2,'0')}:${String(ms%60).padStart(2,'0')}`;}
function timerPage(){const cfg=intervalConfig;let ph=interval?.phases?.[interval.index],remaining=interval?interval.paused?interval.remainingMs:interval.endsAt-Date.now():0,total=ph?ph.minutes*60000:1;return `<div class="section-intro"><div><div class="eyebrow">CARDIO & TAPIS</div><h1>Intervalles guidés</h1><p class="lede">Un minuteur clair pour chaque phase.</p></div></div><div class="desktop-cols"><section class="panel"><div class="eyebrow" style="text-align:center">${interval?`PHASE ${Math.min(interval.index+1,interval.phases.length)} SUR ${interval.phases.length}`:'PROGRAMME LIBRE'}</div><div class="timer-visual" id="timer-wheel" style="--timer-pct:${interval?clamp(100*(1-remaining/total),0,100):0}%"><div><small id="timer-phase">${esc(ph?.label||'Prêt à courir')}</small><strong id="timer-clock">${interval?countdown(remaining):'00:00'}</strong></div></div><div class="timer-stage" id="timer-stage">${interval?'Maintiens le rythme':'Configure tes intervalles'}</div><div class="btnrow" style="justify-content:center;margin-top:22px">${interval?`<button class="btn ${interval.paused?'accent':'outline'}" data-action="timer-pause">${icon(interval.paused?'play':'pause')} ${interval.paused?'Reprendre':'Pause'}</button><button class="btn warn" data-action="timer-stop">${icon('close')} Arrêter</button>`:`<button class="btn accent" data-action="timer-start">${icon('play')} Démarrer les intervalles</button>`}</div><div class="alert" style="margin-top:18px">Sur iPhone, les alertes et le chronomètre ne sont pas garantis en arrière-plan. Garde l'application ouverte pendant les intervalles.</div></section><section class="panel"><h3>Paramètres</h3><div class="timer-config">${[['warmup','Échauffement (min)'],['rounds','Répétitions'],['work','Effort (min)'],['rest','Récup. (min)'],['cooldown','Retour calme (min)'],['workIncline','Pente cible (%)']].map(([k,label])=>`<div class="field"><label>${label}</label><input type="number" inputmode="decimal" min="0" step="any" value="${esc(cfg[k])}" data-interval="${k}" ${interval?'disabled':''}></div>`).join('')}</div><div class="field" style="margin-top:10px"><label>Vitesse cible (km/h, facultatif)</label><input type="text" data-interval="workSpeed" value="${esc(cfg.workSpeed)}" placeholder="Par ex. 9–12" ${interval?'disabled':''}></div><div class="softcall" style="margin-top:15px"><strong>Durée totale : ${formatNumber(buildPhases(cfg).reduce((a,b)=>a+b.minutes,0))} min</strong><p style="margin-top:5px">${cfg.warmup} min d'échauffement · ${cfg.rounds} × (${cfg.work} min effort + ${cfg.rest} min récupération) · ${cfg.cooldown} min retour au calme.</p></div></section></div>`;}
function modalHtml(){if(!modal)return '';let body='',heading='';if(modal==='session'){heading=draft?.id?'Modifier la séance':'Nouvelle séance';body=`<div class="formgrid"><div class="field full"><label>Nom de la séance</label><input data-draft="title" value="${esc(draft.title)}" required placeholder="Ex. Sortie trail en forêt"></div><div class="field"><label>Date</label><input type="date" data-draft="date" value="${esc(draft.date)}"></div><div class="field"><label>Catégorie</label><select data-draft="type">${['force','cardio','mixte'].map(x=>`<option value="${x}" ${draft.type===x?'selected':''}>${category(x)}</option>`).join('')}</select></div><div class="field"><label>Durée estimée (min)</label><input type="number" min="1" max="600" data-draft="durationMin" value="${esc(draft.durationMin||45)}"></div><div class="field full"><label>Objectif de la séance</label><textarea data-draft="description">${esc(draft.description||'')}</textarea></div></div><div class="row spread" style="margin:19px 0 8px"><h3>Exercices (${draft.exercises.length})</h3><button class="btn outline small" data-action="draft-add-ex">${icon('plus',14)} Libre</button></div>${draft.exercises.map((e,i)=>`<div class="exrow"><div class="row spread"><strong>Exercice ${i+1}</strong><div class="btnrow"><button class="btn ghost icon-only" title="Monter l'exercice" data-action="draft-move-ex" data-index="${i}" data-dir="-1" ${i===0?'disabled':''}>↑</button><button class="btn ghost icon-only" title="Descendre l'exercice" data-action="draft-move-ex" data-index="${i}" data-dir="1" ${i===draft.exercises.length-1?'disabled':''}>↓</button><button class="btn ghost icon-only" title="Supprimer" data-action="draft-del-ex" data-index="${i}">${icon('trash',16)}</button></div></div><div class="formgrid"><div class="field full"><label>Nom</label><input data-exidx="${i}" data-exfield="name" value="${esc(e.name)}"></div><div class="field"><label>Volume (ex. 3 × 10)</label><input data-exidx="${i}" data-exfield="volume" value="${esc(e.volume||'')}"></div><div class="field"><label>Charge indicative</label><input data-exidx="${i}" data-exfield="load" value="${esc(e.load||'')}"></div><div class="field full"><label>Consigne technique</label><input data-exidx="${i}" data-exfield="description" value="${esc(e.description||'')}"></div></div></div>`).join('')}<div class="field"><label>Ajouter depuis la bibliothèque</label><select id="library-select"><option value="">Choisir un exercice...</option>${allExerciseNames().map((x,i)=>`<option value="${i}">${esc(x.name)}</option>`).join('')}</select></div><button class="btn outline block" style="margin-top:9px" data-action="draft-add-library">${icon('plus')} Ajouter cet exercice</button><div class="divider"></div><div class="btnrow"><button class="btn accent grow" data-action="save-session">${icon('check')} Enregistrer la séance</button>${draft?.id?`<button class="btn warn" data-action="delete-session">${icon('trash')}</button>`:''}</div>`;
}else if(modal==='measure'){heading='Nouvelle mesure';body=`<div class="formgrid"><div class="field full"><label>Date</label><input type="date" data-measure="date" value="${esc(draft.date)}"></div>${[['weight','Poids (kg)'],['waist','Tour de taille (cm)'],['chest','Tour de poitrine (cm)'],['hips','Tour de hanches (cm)'],['arm','Tour de bras (cm)'],['thigh','Tour de cuisse (cm)']].map(([k,label])=>`<div class="field"><label>${label}</label><input type="number" inputmode="decimal" step="any" min="0" data-measure="${k}" placeholder="Facultatif" value="${esc(draft[k]||'')}"></div>`).join('')}</div><div class="divider"></div><button class="btn accent block" data-action="save-measure">${icon('check')} Enregistrer la mesure</button>`;
}else if(modal==='exercise'){heading='Créer un exercice';body=`<div class="formgrid"><div class="field full"><label>Nom</label><input data-custom-ex="name" value="${esc(draft.name||'')}"></div><div class="field"><label>Volume habituel</label><input data-custom-ex="volume" value="${esc(draft.volume||'3 x 10')}"></div><div class="field"><label>Charge indicative</label><input data-custom-ex="load" value="${esc(draft.load||'')}"></div><div class="field full"><label>Consigne</label><textarea data-custom-ex="description">${esc(draft.description||'')}</textarea></div></div><div class="divider"></div><button class="btn accent block" data-action="save-exercise">${icon('check')} Ajouter à ma bibliothèque</button>`;}
return `<div class="modal-overlay" role="presentation" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(heading)}" data-modal-interior="true"><div class="modal-head"><h2>${esc(heading)}</h2><button class="btn outline icon-only" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></div>${body}</div></div>`;}
function render(){const view=page==='home'?home():page==='calendar'?calendar():page==='trainings'?trainings():page==='stats'?stats():page==='profile'?profile():page==='session'?sessionDetails():page==='timer'?timerPage():home();const navs=[['home','Accueil','home'],['calendar','Planning','calendar'],['trainings','Séances','weight'],['stats','Progrès','stats'],['profile','Profil','user']];const navActive=page==='session'?'trainings':page==='timer'?'trainings':page;app.innerHTML=`<div class="wrap"><header class="topbar"><div class="brand"><span class="brand-mark">↗</span><span>MakeItHybrid<span style="color:var(--accent)">.</span></span></div><div class="toplinks"><span class="topdate">${formatDate(todayISO(),{weekday:'long',day:'numeric',month:'long'})}</span><button class="avatar" data-action="nav" data-page="profile" title="Profil">${icon('user',20)}</button></div></header><main>${view}</main></div><nav class="nav" aria-label="Navigation principale">${navs.map(([id,label,ic])=>`<button class="${navActive===id?'active':''}" data-action="nav" data-page="${id}" aria-label="${label}">${icon(ic)}<span>${label}</span></button>`).join('')}</nav>${modalHtml()}`;if(restTimer)updateRest();if(page==='timer')updateTimerDisplay();}
function setModal(which,obj){modal=which;draft=structuredClone(obj);render();}
function openEditor(session){const item=session?structuredClone(session):{id:null,date:selectedDate,title:'',description:'',type:'force',durationMin:45,exercises:[]};setModal('session',item);}
function parseVolume(ex){const m=String(ex.volume||'').match(/^\s*(\d+)\s*x\s*(\d+)(?!\s*\+)/i);if(m&&!String(ex.volume).includes('(')){ex.sets=+m[1];ex.reps=+m[2];}else{ex.sets=null;ex.reps=null;}return ex;}
function storeEditor(){if(!draft.title.trim())return toast('Indique un nom de séance.');if(!/^\d{4}-\d{2}-\d{2}$/.test(draft.date))return toast('La date est incorrecte.');if(!['force','cardio','mixte'].includes(draft.type))return toast('Catégorie invalide.');const obj={...draft,title:draft.title.trim(),date:draft.date,durationMin:clamp(validNum(draft.durationMin),1,600),durationLabel:`${clamp(validNum(draft.durationMin),1,600)} min`,exercises:draft.exercises.filter(e=>e.name.trim()).map(e=>parseVolume({...e,id:e.id||uniqueId('exercise'),name:e.name.trim()}))};if(draft.id){state.sessions=state.sessions.map(s=>s.id===draft.id?obj:s);}else{obj.id=uniqueId('session');obj.week=null;state.sessions.push(obj);}modal=null;selectedDate=obj.date;sessionId=obj.id;page='session';persist();render();toast('Séance enregistrée');}
function startSession(id){const s=sget(id);if(!s)return;let l=inProgress(id);if(!l){l=initialLog(s);const history=state.logs.filter(x=>x.finishedAt).sort((a,b)=>b.date.localeCompare(a.date));for(const e of l.exercises){let previous=history.flatMap(x=>x.exercises||[]).find(x=>x.name.toLowerCase().trim()===e.name.toLowerCase().trim());if(previous){const previousDone=previous.sets.filter(a=>a.done);for(let i=0;i<e.sets.length;i++){if(previousDone[i]?.kg!==undefined)e.sets[i].kg=previousDone[i].kg;}}}state.logs.push(l);}sessionId=id;page='session';persist();render();toast('Séance démarrée');}
function finishSession(){const s=sget(sessionId),l=inProgress(sessionId);if(!s||!l)return;if(!confirm('Terminer cette séance et enregistrer les performances ?'))return;l.finishedAt=new Date().toISOString();l.elapsedMinutes=Math.max(0,Math.round((Date.now()-new Date(l.startedAt).getTime())/60000));if(!validNum(l.cardio.durationMin))l.cardio.durationMin=l.elapsedMinutes;persist();render();toast('Séance terminée ✓');}
function exportFile(name,blob){const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportJSON(){exportFile(`makeithybrid-sauvegarde-${todayISO()}.json`,new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json;charset=utf-8'}));toast('Sauvegarde complète exportée');}
function csvQuote(v){return '"'+String(v??'').replaceAll('"','""')+'"';}
function exportCSV(){const headers=['Date','Séance','Catégorie','Exercice','Série','Charge kg','Répétitions','Validée','Durée min','Distance km','Dénivelé + m','RPE séance','Notes'];const rows=[headers,...state.logs.map(l=>l.exercises.length?l.exercises.flatMap(e=>e.sets.map((a,i)=>[l.date,l.title,l.type,e.name,i+1,a.kg,a.reps,a.done?'Oui':'Non',l.cardio.durationMin,l.cardio.distance,l.cardio.elevation,l.rpe,l.notes])):[[l.date,l.title,l.type,'','','','','',l.cardio.durationMin,l.cardio.distance,l.cardio.elevation,l.rpe,l.notes]]).flat()];const data='\ufeff'+rows.map(x=>x.map(csvQuote).join(';')).join('\r\n');exportFile(`makeithybrid-entrainements-${todayISO()}.csv`,new Blob([data],{type:'text/csv;charset=utf-8'}));toast('CSV exporté');}
function updateRest(){if(!restTimer)return;const el=$('#rest-strip');if(!el)return;const remaining=restTimer.paused?restTimer.remaining:Math.max(0,restTimer.end-Date.now());if(remaining<=0){restTimer=null;el.classList.add('hide');notifyTick();toast('Repos terminé');return;}el.classList.remove('hide');el.innerHTML=`<div class="row spread"><strong>${icon('clock',15)} Repos : ${countdown(remaining)}</strong><div class="btnrow"><button class="btn small outline" data-action="rest-pause">${restTimer.paused?'Reprendre':'Pause'}</button><button class="btn small ghost" data-action="rest-stop">${icon('close',14)}</button></div></div>`;}
function notifyTick(){try{if(navigator.vibrate)navigator.vibrate([120,80,120]);const ctx=new (window.AudioContext||window.webkitAudioContext)(),osc=ctx.createOscillator(),gain=ctx.createGain();osc.frequency.value=880;gain.gain.value=.035;osc.connect(gain).connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.15);setTimeout(()=>ctx.close(),350);}catch(e){/* sons non garantis */}}
function timerTick(){if(!interval||interval.paused)return;let i=interval.index;let end=interval.endsAt;let changed=false;while(i<interval.phases.length&&end<=Date.now()){i++;changed=true;if(i<interval.phases.length)end+=interval.phases[i].minutes*60000;}if(changed){if(i>=interval.phases.length){interval=null;if(page==='timer')render();notifyTick();toast('Intervalles terminés !');return;}interval.index=i;interval.endsAt=end;notifyTick();if(page==='timer')render();}if(page==='timer')updateTimerDisplay();}
function updateTimerDisplay(){if(!interval)return;const ph=interval.phases[interval.index];const remaining=interval.paused?interval.remainingMs:interval.endsAt-Date.now();const tot=ph.minutes*60000,el=$('#timer-wheel');if(el)el.style.setProperty('--timer-pct',`${clamp(100*(1-remaining/tot),0,100)}%`);if($('#timer-clock'))$('#timer-clock').textContent=countdown(remaining);if($('#timer-phase'))$('#timer-phase').textContent=ph.label;if($('#timer-stage'))$('#timer-stage').textContent=ph.phase==='work'?`Effort · ${intervalConfig.workIncline?intervalConfig.workIncline+' % de pente':''} ${intervalConfig.workSpeed?intervalConfig.workSpeed+' km/h':''}`:ph.phase==='rest'?'Récupère, prépare la prochaine répétition':'Rythme facile et progressif';}
async function restoreJSON(file){try{if(!file)return;const contents=await file.text();if(contents.length>20000000)throw new Error('Fichier trop volumineux');const obj=JSON.parse(contents);if(!obj||!Array.isArray(obj.sessions)||!Array.isArray(obj.logs)||!Array.isArray(obj.measures)||obj.sessions.some(s=>!s.id||!s.date||!Array.isArray(s.exercises)))throw new Error('Structure de sauvegarde invalide');if(!confirm('Restaurer cette sauvegarde ? Les données actuelles seront remplacées. Exporte-les d’abord si tu souhaites les conserver.'))return;state={...state,...obj,customExercises:Array.isArray(obj.customExercises)?obj.customExercises:[],archivedSessions:Array.isArray(obj.archivedSessions)?obj.archivedSessions:[],profile:obj.profile||state.profile,schemaVersion:1};modal=null;page='home';selectedDate=todayISO();persist();render();toast('Sauvegarde restaurée ✓');}catch(e){console.error(e);alert(`Import impossible : ${e.message}`);}finally{const el=$('#import-file');if(el)el.value='';}}
function go(pageId){page=pageId;modal=null;render();window.scrollTo(0,0);}
function confirmDel(s){const hasLogs=logsOf(s.id).length>0;let msg=hasLogs?'Retirer cette séance du calendrier ? Son historique sera conservé.':'Supprimer définitivement cette séance du planning ?';if(!confirm(msg))return;state.sessions=state.sessions.filter(x=>x.id!==s.id);if(hasLogs&&!state.archivedSessions.some(x=>x.id===s.id))state.archivedSessions.push(s);modal=null;go('calendar');persist();toast(hasLogs?'Séance retirée, historique conservé':'Séance supprimée');}
function handleAction(event){const btn=event.target.closest('[data-action]');if(!btn)return;const action=btn.dataset.action;if(action==='close-modal'&&btn.classList.contains('modal-overlay')&&event.target.closest('[data-modal-interior]'))return;event.preventDefault();switch(action){
 case 'nav':go(btn.dataset.page);break;
 case 'view-session':sessionId=btn.dataset.id;go('session');break;
 case 'go-week':selectedDate=shiftDay(weekStart,(+btn.dataset.week-1)*7);go('calendar');break;
 case 'select-day':selectedDate=btn.dataset.date;render();break;
 case 'today':selectedDate=todayISO();render();break;
 case 'change-week':selectedDate=shiftDay(selectedDate,Number(btn.dataset.direction)*7);render();break;
 case 'calendar-mode':calendarView=btn.dataset.mode;render();break;
 case 'new-session':openEditor(null);break;
 case 'edit-session':openEditor(sget(btn.dataset.id));break;
 case 'duplicate':{const x=sget(btn.dataset.id);if(!x)return;const obj=structuredClone(x);obj.id=null;obj.week=null;obj.date=selectedDate;obj.title+=' (copie)';obj.exercises=obj.exercises.map(e=>({...e,id:uniqueId('ex')}));openEditor(obj);break;}
 case 'close-modal':modal=null;draft=null;render();break;
 case 'draft-add-ex':draft.exercises.push({id:uniqueId('ex'),name:'',volume:'3 x 10',load:'',description:'',sets:3,reps:10});render();break;
 case 'draft-del-ex':draft.exercises.splice(+btn.dataset.index,1);render();break;
 case 'draft-move-ex':{const i=+btn.dataset.index,j=i+(+btn.dataset.dir);if(j>=0&&j<draft.exercises.length){const [a]=draft.exercises.splice(i,1);draft.exercises.splice(j,0,a);render();}break;}
 case 'draft-add-library':{const sel=$('#library-select');if(!sel||sel.value==='')return toast('Sélectionne un exercice.');const e=allExerciseNames()[+sel.value];draft.exercises.push({...structuredClone(e),id:uniqueId('ex')});render();break;}
 case 'save-session':storeEditor();break;
 case 'delete-session':{const s=sget(draft.id);if(s)confirmDel(s);break;}
 case 'start-session':startSession(btn.dataset.id);break;
 case 'restart-session':startSession(btn.dataset.id);break;
 case 'finish-session':finishSession();break;
 case 'toggle-set':{const l=inProgress(sessionId);if(!l)return;const a=l.exercises[+btn.dataset.eidx].sets[+btn.dataset.sidx];a.done=!a.done;persist();render();break;}
 case 'add-set':{const l=inProgress(sessionId);if(!l)return;const e=l.exercises[+btn.dataset.eidx],prev=e.sets.at(-1);e.sets.push({id:uniqueId('set'),kg:prev?.kg||'',reps:prev?.reps||'',done:false,rpe:''});persist();render();break;}
 case 'rest-start':restTimer={end:Date.now()+(+btn.dataset.seconds||90)*1000,paused:false,remaining:0};updateRest();break;
 case 'rest-pause':if(restTimer){if(restTimer.paused){restTimer.end=Date.now()+restTimer.remaining;restTimer.paused=false;}else{restTimer.remaining=restTimer.end-Date.now();restTimer.paused=true;}updateRest();}break;
 case 'rest-stop':restTimer=null;$('#rest-strip')?.classList.add('hide');break;
 case 'open-timer':{const s=sget(btn.dataset.id);intervalConfig=presetFor(s);go('timer');break;}
 case 'timer-start':{const phases=buildPhases(intervalConfig);if(!phases.length)return toast('Ajoute au moins une étape.');if(phases.some(p=>p.minutes>240)||phases.length>100)return toast('Séance trop longue : réduis les paramètres.');interval={phases,index:0,endsAt:Date.now()+phases[0].minutes*60000,paused:false,remainingMs:0};render();toast('Intervalles démarrés');break;}
 case 'timer-pause':if(!interval)return;if(interval.paused){interval.endsAt=Date.now()+interval.remainingMs;interval.paused=false;}else{interval.remainingMs=Math.max(0,interval.endsAt-Date.now());interval.paused=true;}render();break;
 case 'timer-stop':if(interval&&confirm('Arrêter le chronomètre ?')){interval=null;render();}break;
 case 'metric':chartType=btn.dataset.metric;render();break;
 case 'new-measure':setModal('measure',{date:todayISO(),weight:'',waist:'',chest:'',hips:'',arm:'',thigh:''});break;
 case 'save-measure':{if(!/^\d{4}-\d{2}-\d{2}$/.test(draft.date))return toast('Date invalide');const metric=['weight','waist','chest','hips','arm','thigh'];if(!metric.some(k=>validNum(draft[k])>0))return toast('Saisis au moins une mesure.');const m={id:uniqueId('measure'),date:draft.date};for(const k of metric){m[k]=draft[k]!==''?validNum(draft[k]):null;if(m[k]!=null&&(m[k]<=0||m[k]>1000))return toast('Vérifie les valeurs saisies.');}state.measures.push(m);modal=null;persist();render();toast('Mesure enregistrée');break;}
 case 'delete-measure':if(confirm('Supprimer cette mesure ?')){state.measures=state.measures.filter(m=>m.id!==btn.dataset.id);persist();render();}break;
 case 'new-exercise':setModal('exercise',{name:'',volume:'3 x 10',load:'',description:''});break;
 case 'save-exercise':if(!draft.name.trim())return toast('Indique un nom.');state.customExercises.push({...draft,id:uniqueId('customex'),name:draft.name.trim()});modal=null;persist();render();toast('Exercice ajouté');break;
 case 'delete-exercise':if(confirm('Supprimer cet exercice personnalisé de la bibliothèque ? Les séances déjà enregistrées ne seront pas modifiées.')){state.customExercises=state.customExercises.filter(e=>e.id!==btn.dataset.id);persist();render();}break;
 case 'export-json':exportJSON();break;
 case 'export-csv':exportCSV();break;
 case 'trigger-import':$('#import-file')?.click();break;
 default:console.warn('Action inconnue',action);
}}
function handleInput(e){const el=e.target;if(el.dataset.setfield){const l=inProgress(sessionId);if(!l)return;const a=l.exercises[+el.dataset.eidx]?.sets[+el.dataset.sidx];if(a){a[el.dataset.setfield]=el.value;persist();}}else if(el.dataset.cardiofield){const l=inProgress(sessionId);if(l){l.cardio[el.dataset.cardiofield]=el.value;persist();if($('#cardio-preview'))$('#cardio-preview').innerHTML=cardioPreview(l);}}else if(el.dataset.logfield){const l=inProgress(sessionId);if(l){l[el.dataset.logfield]=el.value;persist();}}else if(el.dataset.draft){if(draft)draft[el.dataset.draft]=el.value;}else if(el.dataset.exfield!==undefined){const ex=draft?.exercises?.[+el.dataset.exidx];if(ex)ex[el.dataset.exfield]=el.value;}else if(el.dataset.measure){if(draft)draft[el.dataset.measure]=el.value;}else if(el.dataset.customEx){if(draft)draft[el.dataset.customEx]=el.value;}else if(el.dataset.interval){const k=el.dataset.interval;intervalConfig[k]=['workIncline','workSpeed'].includes(k)?el.value:validNum(el.value);}else if(el.dataset.profile){state.profile[el.dataset.profile]=el.value;persist();}}
function handleChange(e){const el=e.target;if(el.id==='import-file')restoreJSON(el.files?.[0]);else if(el.dataset.interval&&page==='timer'&&!interval)render();}
async function init(){let program=[];try{const res=await fetch('./public/programme.json');if(!res.ok)throw new Error('Programme introuvable');program=await res.json();}catch(err){console.error(err);app.innerHTML=`<div class="initial-loader"><h2>Impossible de charger le programme.</h2><p>Ouvre l'application depuis un serveur web (HTTPS ou localhost), pas directement comme un fichier.</p></div>`;return;}
 try{state=await loadState();}catch(e){console.warn('IDB non disponible',e);try{state=JSON.parse(localStorage.getItem('hybridtrack-fallback')||'null');storageMode='Stockage de secours';}catch(err){state=null;storageMode='Sauvegarde indisponible';}}
 if(!state){state={schemaVersion:1,sessions:program,archivedSessions:[],logs:[],measures:[],customExercises:[],profile:{height:'189',goal:'hybrid',raceName:'Sierre-Zinal 2027',raceDate:'2027-08-07',restSeconds:'90',raceDistance:'31',raceElevation:'2200'}};persist();}
 state.sessions=Array.isArray(state.sessions)?state.sessions:program;state.logs=Array.isArray(state.logs)?state.logs:[];state.measures=Array.isArray(state.measures)?state.measures:[];state.customExercises=Array.isArray(state.customExercises)?state.customExercises:[];state.archivedSessions=Array.isArray(state.archivedSessions)?state.archivedSessions:[];state.profile=state.profile||{height:'189',goal:'hybrid',raceName:'Sierre-Zinal 2027',raceDate:'2027-08-07',restSeconds:'90',raceDistance:'31',raceElevation:'2200'};
 document.addEventListener('click',handleAction);document.addEventListener('input',handleInput);document.addEventListener('change',handleChange);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=null;render();}});
 setInterval(()=>{if(restTimer&&!restTimer.paused)updateRest();timerTick();},250);
 render();if('serviceWorker' in navigator&&location.protocol!=='file:'){navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('PWA offline indisponible',e));}}
init();
